pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate, uint128 _virtualBaseTokenReserves, uint128 _virtualNftReserves, uint56 _changeFee) public {
        vm.assume(_feeRate <= 5000);
        c.initialize(address(0), address(0), _virtualBaseTokenReserves, _virtualNftReserves, _changeFee, _feeRate, bytes32(0), false, false);
        assertTrue(c.feeRate() == _feeRate);
    }
}
